//! Stylesheets; every expected value was produced by WordPress 7.1.5, compared byte for byte.
//!
//! Generated by `.superpowers/gen_stylesheet.py`; edit the generator, not the cases.

#![allow(unused_variables)] // Each case builds a document, whether its call reads it or not.

mod support;

use std::rc::Rc;

use speedyspec_hooks::Value;
use speedyspec_wp_theme_json::{
    MemoryGlobalSettings, MemoryThemeSupports, RecordedDiagnostics, ThemeJsonApi, ThemeJsonDeps,
};
use speedyspec_wp_theme_json_contracts::ThemeJsonError;
use speedyspec_wp_theme_json_contracts::ports::ThemeJsonFilters;
use support::core_blocks::core_blocks;
use support::{assert_php_same as assert_php_eq, deps, json, php_list, st};

struct Harness {
    deps: ThemeJsonDeps,
    notices: Rc<RecordedDiagnostics>,
    theme: Rc<MemoryThemeSupports>,
}

impl Harness {
    fn new(global: Value) -> Harness {
        let (deps, notices) = deps(core_blocks());
        let theme = Rc::new(MemoryThemeSupports::default());
        let deps = deps
            .with_global_settings(Rc::new(MemoryGlobalSettings::new(global)))
            .with_theme(theme.clone());
        Harness {
            deps,
            notices,
            theme,
        }
    }
    fn api(&self) -> ThemeJsonApi {
        ThemeJsonApi::new(self.deps.clone())
    }
    fn notices(&self) -> Vec<String> {
        self.notices.notices.borrow().clone()
    }
}

fn pair(data: Value, notices: Vec<String>) -> Value {
    php_list(vec![
        data,
        php_list(notices.into_iter().map(Value::Str).collect()),
    ])
}

/// A `wp_theme_json_get_style_nodes` callback that reverses the list.
struct Reverse;

impl ThemeJsonFilters for Reverse {
    fn style_nodes(&self, nodes: Value) -> Result<Value, ThemeJsonError> {
        let Value::Array(items) = nodes else {
            return Ok(nodes);
        };
        Ok(php_list(items.into_iter().rev().map(|(_, v)| v).collect()))
    }
}

/// A `wp_theme_json_get_style_nodes` callback that drops the root node.
struct DropRoot;

impl ThemeJsonFilters for DropRoot {
    fn style_nodes(&self, nodes: Value) -> Result<Value, ThemeJsonError> {
        let Value::Array(items) = nodes else {
            return Ok(nodes);
        };
        Ok(php_list(
            items
                .into_iter()
                .map(|(_, v)| v)
                .filter(|v| {
                    speedyspec_wp_theme_json::array_path::get(v, &["selector"])
                        != Some(&Value::Str("body".into()))
                })
                .collect(),
        ))
    }
}

